import{_ as a,o as n,c as e,a2 as p}from"./chunks/framework.DqYch1Cg.js";const u=JSON.parse('{"title":"NestJS 请求生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"学习自测/18nestjs/q_nestjs_7-request_lifecycle.md","filePath":"学习自测/18nestjs/q_nestjs_7-request_lifecycle.md","lastUpdated":1794211306000}'),r={name:"学习自测/18nestjs/q_nestjs_7-request_lifecycle.md"};function t(l,s,i,c,d,o){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="nestjs-请求生命周期" tabindex="-1">NestJS 请求生命周期 <a class="header-anchor" href="#nestjs-请求生命周期" aria-label="Permalink to &quot;NestJS 请求生命周期&quot;">​</a></h1><blockquote><p>以下以常规 HTTP Controller 请求为例。服务如何启动和关闭，见<a href="./q_nestjs_6-app_lifecycle">应用生命周期</a>。</p></blockquote><h2 id="_1-客户端发起请求后-nestjs-的完整处理流程是什么" tabindex="-1">1. 客户端发起请求后，NestJS 的完整处理流程是什么？ <a class="header-anchor" href="#_1-客户端发起请求后-nestjs-的完整处理流程是什么" aria-label="Permalink to &quot;1. 客户端发起请求后，NestJS 的完整处理流程是什么？&quot;">​</a></h2><details class="details custom-block"><summary>参考回答</summary><p>一次正常的 HTTP 请求，会先经过 Middleware，再到 Guard，然后进入 Interceptor，接着由 Pipe 转换和校验参数，再执行 Controller，按需调用 Service 处理业务。处理完成后，经过 Interceptor 的返回阶段，最后发送响应。</p><p>这里 Middleware 处理通用请求信息，Guard 判断能不能访问，Pipe 负责参数转换和校验，Controller 协调业务调用。Interceptor 会环绕后续执行，适合做耗时统计和响应转换。多个拦截器进入时从外到内，返回时从内到外。</p><p>如果中间出现未被捕获的异常，就进入异常处理分支，由匹配的 Exception Filter 或 Nest 默认异常处理机制返回错误响应。成功请求不会经过 Filter。</p></details><p><strong>回答节奏</strong>：先按顺序说出正常链路，再补充职责和异常分支，控制在一到两分钟。</p><p><strong>追问入口</strong>：Interceptor 能捕获 Guard 的异常吗？多个拦截器的执行顺序是什么？</p><h2 id="正常请求流程" tabindex="-1">正常请求流程 <a class="header-anchor" href="#正常请求流程" aria-label="Permalink to &quot;正常请求流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端发送 HTTP 请求</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Middleware</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Guard</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Interceptor：进入阶段</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Pipe</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Controller 处理方法</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>按需调用 Service、数据库等</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Interceptor：返回阶段</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>发送 HTTP 响应</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>客户端收到响应</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>这是后续处理被正常放行时的主线。Middleware 可以提前返回响应，Interceptor 也可以直接返回缓存等结果，让请求跳过后续业务处理。</p><p><strong>Service 是常见的业务分层，不是框架强制规定的生命周期步骤。</strong> Controller 可以调用 Service，也可以直接返回结果。</p><h2 id="各阶段负责什么" tabindex="-1">各阶段负责什么？ <a class="header-anchor" href="#各阶段负责什么" aria-label="Permalink to &quot;各阶段负责什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>核心职责</th><th>例子</th></tr></thead><tbody><tr><td>Middleware</td><td>处理通用请求信息</td><td>requestId、请求上下文</td></tr><tr><td>Guard</td><td>判断是否允许进入处理器</td><td>认证、接口权限检查</td></tr><tr><td>Interceptor：进入</td><td>环绕后续执行，添加前置逻辑</td><td>开始计时</td></tr><tr><td>Pipe</td><td>转换和校验处理器参数</td><td><code>ParseIntPipe</code>、DTO 校验</td></tr><tr><td>Controller</td><td>接收参数、协调业务调用</td><td>调用笔记保存服务</td></tr><tr><td>Service（按需调用）</td><td>执行业务规则与数据操作</td><td>检查归属、条件更新</td></tr><tr><td>Interceptor：返回</td><td>转换结果、观测完成或错误</td><td>统一响应结构、记录耗时</td></tr></tbody></table><p>这里是常见职责划分。例如依赖具体业务数据的资源归属检查，也可以放在 Service 中，不必全部写在 Guard。</p><h2 id="多个组件如何排序" tabindex="-1">多个组件如何排序？ <a class="header-anchor" href="#多个组件如何排序" aria-label="Permalink to &quot;多个组件如何排序？&quot;">​</a></h2><h3 id="guard-从外到内" tabindex="-1">Guard：从外到内 <a class="header-anchor" href="#guard-从外到内" aria-label="Permalink to &quot;Guard：从外到内&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全局 Guard → Controller 级 Guard → 路由方法级 Guard</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>同一层级通常按绑定顺序执行。某个 Guard 拒绝后，后续正常处理链不再执行。</p><h3 id="interceptor-进入从外到内-返回从内到外" tabindex="-1">Interceptor：进入从外到内，返回从内到外 <a class="header-anchor" href="#interceptor-进入从外到内-返回从内到外" aria-label="Permalink to &quot;Interceptor：进入从外到内，返回从内到外&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进入：全局 → Controller 级 → 方法级</span></span>
<span class="line"><span>返回：方法级 → Controller 级 → 全局</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这是“洋葱式”执行，同一层级的多个拦截器也按嵌套顺序进入、反向返回。</p><p><strong>Interceptor 环绕的后续处理包括 Pipe 和 Controller，而不只是 Controller 方法本身。</strong> 其中的“返回阶段”也不等于响应已经发给客户端，而是在响应发送前处理结果。</p><h3 id="pipe-从外到内-再到具体参数" tabindex="-1">Pipe：从外到内，再到具体参数 <a class="header-anchor" href="#pipe-从外到内-再到具体参数" aria-label="Permalink to &quot;Pipe：从外到内，再到具体参数&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全局 Pipe → Controller 级 Pipe → 方法级 Pipe → 参数级 Pipe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这表示作用域上的处理顺序；同一参数上的多个 Pipe 按绑定顺序执行。不要据此假设多个参数的解析一定按代码中从左到右串行执行，也不要依赖跨参数 Pipe 的副作用顺序。</p><h3 id="middleware-按注册和模块绑定顺序" tabindex="-1">Middleware：按注册和模块绑定顺序 <a class="header-anchor" href="#middleware-按注册和模块绑定顺序" aria-label="Permalink to &quot;Middleware：按注册和模块绑定顺序&quot;">​</a></h3><p>全局注册的 Middleware 先执行，再执行模块中绑定的 Middleware；具体顺序还取决于注册、模块导入和路由绑定，不能直接套用 Guard 的全局、Controller、方法三级顺序。</p><h2 id="异常是分支-不是正常链路的最后一步" tabindex="-1">异常是分支，不是正常链路的最后一步 <a class="header-anchor" href="#异常是分支-不是正常链路的最后一步" aria-label="Permalink to &quot;异常是分支，不是正常链路的最后一步&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>处理过程中发生异常</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>当前执行链是否捕获并处理？</span></span>
<span class="line"><span>    ├─ 是 → 按处理后的结果继续或结束</span></span>
<span class="line"><span>    └─ 否 → 匹配的 Exception Filter 或 Nest 默认异常处理</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>            返回错误响应</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><ul><li><strong>Guard 返回 <code>false</code></strong>：通常产生 403，不进入后面的 Interceptor、Pipe、Controller；Guard 也可以主动抛出其他异常。</li><li><strong>Pipe 校验失败</strong>：通常产生 400，不执行 Controller；具体状态码取决于 Pipe 的实现和配置。</li><li><strong>Service 抛出异常</strong>：可能先被 Interceptor 的错误处理捕获；未处理时，再交给异常过滤器。</li></ul><p><strong>Guard 在 Interceptor 之前执行，所以后面的 Interceptor 无法捕获 Guard 抛出的异常。</strong> Pipe 和 Controller 则在拦截器包裹的执行链内，异常可以通过 RxJS 的 <code>catchError</code> 等方式处理。</p><p>Exception Filter 通常按更具体的作用域优先匹配：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>方法级 → Controller 级 → 全局</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>匹配的 Filter 处理异常后，不会像拦截器那样继续逐层向外传递。没有自定义 Filter 时，Nest 也有默认异常处理机制，<strong>成功请求不需要经过 Exception Filter</strong>。</p><h2 id="学习场景-保存一篇笔记" tabindex="-1">学习场景：保存一篇笔记 <a class="header-anchor" href="#学习场景-保存一篇笔记" aria-label="Permalink to &quot;学习场景：保存一篇笔记&quot;">​</a></h2><p>假设后续使用 NestJS + PostgreSQL 实现笔记保存接口：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端提交笔记</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Middleware 建立 requestId</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Guard 检查登录身份</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Interceptor 开始计时</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Pipe 校验 DTO</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Controller 调用保存服务</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Service 检查归属、执行版本条件更新</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Interceptor 转换返回结果、记录耗时</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>客户端收到响应</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>如果版本条件不匹配，Service 可以抛出 <code>ConflictException</code>；未被其他逻辑处理时，由异常处理机制返回 409 响应。</p><h2 id="记忆主线" tabindex="-1">记忆主线 <a class="header-anchor" href="#记忆主线" aria-label="Permalink to &quot;记忆主线&quot;">​</a></h2><p><strong>中间件 → 守卫 → 拦截器进入 → 管道 → 业务处理 → 拦截器返回；未处理异常走过滤器分支。</strong></p><p>继续复习：<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_5-middleware_guard">中间件与守卫</a>、<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_6-interceptor_pipe">拦截器与管道</a>、<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_7-exception_filter">异常过滤器</a>。</p><blockquote><p>来源：<a href="https://docs.nestjs.com/faq/request-lifecycle" target="_blank" rel="noreferrer">NestJS 官方文档：Request lifecycle</a></p></blockquote><blockquote><p>来源：<a href="https://docs.nestjs.com/interceptors" target="_blank" rel="noreferrer">NestJS 官方文档：Interceptors</a></p></blockquote>`,42)])])}const h=a(r,[["render",t]]);export{u as __pageData,h as default};
